recreio_personal_export_profile.value:
((
        "recreio"."personal_exports"."scope"='profile' and "recreio"."personal_exports"."profile_id" is not null and "recreio"."personal_exports"."policy_version">0 and
        (("recreio"."personal_exports"."profile_kind"='adult' and "recreio"."personal_exports"."guardian_reference" is null) or ("recreio"."personal_exports"."profile_kind"='minor' and "recreio"."personal_exports"."guardian_reference" is not null))
      ) or (
        "recreio"."personal_exports"."scope"='account' and "recreio"."personal_exports"."profile_id" is null and "recreio"."personal_exports"."profile_kind" is null and "recreio"."personal_exports"."policy_version" is null and "recreio"."personal_exports"."guardian_reference" is null
      )) is true

recreio_account_participation_state.value:
((
        "recreio"."account_participations"."state"='active' and "recreio"."account_participations"."revision"=1 and "recreio"."account_participations"."operation_id" is null and
        "recreio"."account_participations"."closing_at" is null and "recreio"."account_participations"."closed_at" is null
      ) or (
        "recreio"."account_participations"."state"='closing' and "recreio"."account_participations"."revision"=2 and "recreio"."account_participations"."operation_id" is not null and
        "recreio"."account_participations"."closing_at" is not null and "recreio"."account_participations"."closed_at" is null and "recreio"."account_participations"."updated_at">="recreio"."account_participations"."closing_at"
      ) or (
        "recreio"."account_participations"."state"='closed' and "recreio"."account_participations"."revision"=3 and "recreio"."account_participations"."operation_id" is not null and
        "recreio"."account_participations"."closing_at" is not null and "recreio"."account_participations"."closed_at">="recreio"."account_participations"."closing_at" and "recreio"."account_participations"."updated_at">="recreio"."account_participations"."closed_at"
      )) is true

recreio_renewal_cancellation_review.value:
((
      "recreio"."renewal_cancellations"."state"='review' and "recreio"."renewal_cancellations"."review_code" in ('provider_unavailable','scope_changed','foreign_contract','namespace_mismatch','invalid_evidence')
    ) or ("recreio"."renewal_cancellations"."state"<>'review' and "recreio"."renewal_cancellations"."review_code" is null)) is true

recreio_renewal_cancellation_lease.value:
((
      "recreio"."renewal_cancellations"."lease_token" is null and "recreio"."renewal_cancellations"."lease_until" is null
    ) or (
      "recreio"."renewal_cancellations"."lease_token" is not null and "recreio"."renewal_cancellations"."lease_until">"recreio"."renewal_cancellations"."updated_at" and "recreio"."renewal_cancellations"."state"<>'confirmed'
    )) is true
